import java.io.*;
import java.util.*;

public class TextAnalysisVariant5 {
    static int totalWordsInBraces = 0, maxWordLength = 0;

    public static int countWords(String str) {
        str = str.replaceAll("_", " ");
        str = str.trim().replaceAll(" +", " ");
        String[] tokens = str.split(" ");
        if (tokens.length == 1 && tokens[0].isEmpty()) return 0;
        return tokens.length;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        List<Integer> bracePositions = new ArrayList<>();
        bracePositions.add(-1);
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(' || s.charAt(i) == ')') {
                bracePositions.add(i);
            }
        }
        int i = 1, totalCount = 0, maxWordLen = 0;
        String outsideText = "";
        while (i < bracePositions.size() - 1) {
            int startIdx = bracePositions.get(i);
            int endIdx = bracePositions.get(i + 1);
            String insideStr = s.substring(startIdx + 1, endIdx);
            int countWords = countWords(insideStr);
            totalWordsInBraces += countWords;
            outsideText += "_" + s.substring(bracePositions.get(i - 1) + 1, startIdx);
            i += 2;
        }
        outsideText += "_" + s.substring(bracePositions.get(bracePositions.size() - 1) + 1);
        outsideText = outsideText.replaceAll("_", " ");
        outsideText = outsideText.trim().replaceAll(" +", " ");
        String[] outsideWords = outsideText.split(" ");
        for (String w : outsideWords) {
            if (w.length() > maxWordLen)
                maxWordLen = w.length();
        }
        System.out.print(maxWordLen + " " + totalWordsInBraces);
    }
}
